function isPalindromeList(head) {
  let slow = head
  let fast = head
  while (fast && fast.next) {
    slow = slow.next
    fast = fast.next.next
  }
  // Reverse the list that starts at slow, and point second at its new head.
  let second = slow
  let first = head
  while (second && first) {
    if (first.val !== second.val) return false
    first = first.next
    second = second.next
  }
  return true
}

