type ListNode = { val: number; next: ListNode | null }

function isPalindromeList(head: ListNode | null): boolean {
  let slow = head
  let fast = head
  while (fast && fast.next) {
    slow = slow!.next
    fast = fast.next.next
  }
  let prev: ListNode | null = null
  let second = slow
  while (second) {
    const nxt: ListNode | null = second.next
    second.next = prev
    prev = second
    second = nxt
  }
  second = prev
  let first = head
  while (second && first) {
    if (first.val !== second.val) return false
    first = first.next
    second = second.next
  }
  return true
}
